def calculate_sum(length_b, b):
    b.sort(reverse=True)
    b_sum = sum(b)
    a = list(range(1, length_b + 1))
    slices = [0] + a * b_sum
    end_coor = 0
    for v in b:
        left = bisect_right(slices, v, key=lambda x: x) - 2
        if v == slices[0]:
            return 0
        if left:
            left = next((l for l in range(left, len(slices)) if slices[l] >= v), len(slices) - 1)
            value = g(slices, left - 1 + end_coor + 1, len(a), left - 1)
            end_coor += 1
            slices[left] -= value
            if left - 1 >= 1:
                slices[left - 1] -= slices[value + 1] - slices[value]
    return sum(t / 2 ** x for t, x in zip(slices, a[:end_coor]))

