def find_min_max_values(n: int, k: int, constraints: List[List[int]]) -> None:
    min_values = [float('inf')] * n
    result_values = [None] * n
    index_to_variable = {variable: idx for idx, variable in enumerate(result_values)}

    for i, constraint in enumerate(constraints):
        mapping = set()
        for variable in constraint:
            if variable in index_to_variable:
                mapping.add(index_to_variable[variable])  # Use heap for faster index lookup

        min_value = len(mapping)  # Least used value is the min value
        if min_value == len(result_values):
            min_value = float('inf')

        for idx in mapping:
            min_values[idx] = min(min_values[idx], 0)

        elements_in_min_heap = -min_value  # Heap elements are (value, variable)
        for j in range(i + 1, i + n):
            if j in index_to_variable:  # Fine the variable that causes perspective result change
                variable_index = index_to_variable[j]
                current_variable_value = 0  # To use for calculations, current heap is modified
                for k in constraint:
                    if k in elements_in_min_heap:
                        current_variable_value += 1
                if (min_value - current_variable_value) >= 0:
                    elements_in_min_heap.remove(len(mapping))
                    heappush(elements_in_min_heap, min_value - current_variable_value)

        # Add new variables to min heap
        for j in range(i, i + n):
            if min_values[j] < 0 or (
                (-min_values[j]) + min_value == min_value
                and min_values[j] <= index_to_variable[j]
                and min_values[j] not in elements_in_min_heap
            ) or index_to_variable[j] in elements_in_min_heap:
                elements_in_min_heap.add(-min_values[j])
                heappop(elements_in_min_heap)

        min_value = sorted(elements_in_min_heap)[0]  # min variable with priority as locus of constraints
        result_values[index_to_variable[j] + i * n] = min_value

    print(" ".join(map(str, result_values[::n])))

