def build_poly(n):
    prime_factors = []
    i = 2
    while i <= n:
        prime = True
        for j in prime_factors:
            if i % j == 0: prime = False
            j *= 2
        if prime: prime_factors.append(i)
        i += 1
    poly = [1] + [0] * (n)
    f = {2**i-1: 0 for i in range(1, len(prime_factors))}
    for i in prime_factors:
        pw = i
        while pw <= n:
            for j in range(2, n//pw+1):
                poly[pw*j-1] += f[pw] * j
            poly[pw] += f[pw]
            if pw == 2**f[pw] - 1:
                t = pw
                while t <= n:
                    ipow = 1
                    while t >= 1+ipow*ipow-1:
                        f[t] += f[t-ipow*(t-ipow-1)//2] * ipow
                        t -= 1+ipow*ipow-1
                    ipow += 1
                f.pop(t)
            pw *= i
    return [mod_mul(x, 2) for x in poly]

def mod_mul(x, y):
    return (((x*x) % MOD) * (y >> 1)) % MOD

def solve(n):
    poly = build_poly(2*n - 1)
    sum_rock = 0
    sum_style = 0
    bottom = poly[2*n-3]
    top = poly[2*n-1]

    for i in range(n):
        bottom = mod_mul(bottom, bottom)
        for j in range(1, n+1):
            left = mod_mul(bottom, poly[2*n-1-j]) % MOD
            top = mod_mul(top, mod_mul(poly[i], mod_mul(poly[i+j-1], mod_mul(poly[2*n-2], poly[2*n-1-j])).mod(MOD))).mod(MOD)
            right = mod_mul(top, poly[i]) % MOD
            L = mod_mul(left, mod_mul(right, right)) % MOD
            R = mod_mul(left, mod_mul(poly[i+1], mod_mul(poly[i+j], mod_mul(poly[2*n-2-i], poly[2*n-1-j])).mod(MOD))).mod(MOD)
            sum_rock -= L
            sum_style += R
    return mod_mul(top, sum_rock) % MOD, mod_mul(sum_style, bottom) % MOD

def main():
    n = int(input())
    print(mod_mul(*solve(n)))

