import heapq

def ucs(start, goal, paths, routes):
    dist = {city: float('inf') for city in range(1, n + 1)}
    dist[start] = 0
    queue = [(0, start)]
    used_routes = set()
    used_routes.add(routes[start - 1])

    while queue:
        cur_dist, cur_city = heapq.heappop(queue)
        if cur_city == goal:
            return dist[goal]

        for next_city, next_dist in filter(lambda x: x[0] not in used_routes, paths[cur_city - 1]):
            if dist[next_city] > cur_dist + 1:
                dist[next_city] = cur_dist + 1
                heapq.heappush(queue, (dist[next_city], next_city))
                used_routes.add(routes[next_city - 1])

    return float('inf')

