def solve(N, K, constraints):
    numbers = [i for i in range(1, N + 1)]
    perm_set = set(permutations(numbers))
    min_val = float('inf')
    min_perm = None

    for perm in perm_set:
        valid = True
        for constraint in constraints:
            for index in constraint[1:]:
                if perm[index - 1] < perm[constraint[0] - 1] or (perm[constraint[0] - 1] != 0 and perm[index - 1] > perm[constraint[0] - 1]):
                    valid = False
                    break
            if not valid:
                break
        if valid and max(perm) < min_val:
            min_val = max(perm)
            min_perm = perm

