from math import gcd

def find_path(oranges, apples):
    if oranges == 1 and apples == 1:
        return "Impossible"

    min_value = min(oranges, apples)
    step_val = gcd(gcd(oranges // min_value, apples // min_value), min_value)

    if oranges // step_val < apples // step_val:
        return "3A" * (oranges // step_val) + "1B" * (oranges % step_val)
    else:
        return "3B" * (oranges // step_val) + "1A" * (oranges % step_val)

# Example usage
